-- ─────────────────────────────────────────────────────────────────────────────
-- Migration 005: platform_predictions table
--
-- Stores AI-generated match predictions (one row per match).
-- Generated by the Claude API via /api/predict-match.
--
-- RLS: anyone can read; only the service role can insert/update/delete.
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.platform_predictions (
  id           uuid primary key default uuid_generate_v4(),
  match_id     uuid not null references public.matches(id) on delete cascade,
  home_score   integer not null,
  away_score   integer not null,
  confidence   smallint not null check (confidence between 0 and 100),
  reasoning    text not null,
  generated_at timestamptz not null default now(),

  unique (match_id)   -- one prediction per match, update in place
);

create index if not exists platform_predictions_match_id_idx
  on public.platform_predictions (match_id);

alter table public.platform_predictions enable row level security;

-- Anyone (including anonymous visitors) can read predictions
create policy "platform_predictions_select_all"
  on public.platform_predictions
  for select
  using (true);

-- Only the service role (AI generation route) can insert
create policy "platform_predictions_insert_service_role"
  on public.platform_predictions
  for insert
  with check (auth.role() = 'service_role');

-- Only the service role can update (re-generate a prediction)
create policy "platform_predictions_update_service_role"
  on public.platform_predictions
  for update
  using (auth.role() = 'service_role');

-- Only the service role can delete
create policy "platform_predictions_delete_service_role"
  on public.platform_predictions
  for delete
  using (auth.role() = 'service_role');
